   assert.equal(JSON.stringify((await db.query('SELECT * FROM permit_final_reviews ORDER BY id'))[0]),history);
   assert.equal((await save(kind,[{...approved,engineer_name:'Renamed Reviewer'}])).body.unchanged,true);
   assert.equal((await db.query(`SELECT engineer_name FROM ${table} WHERE id=50`))[0][0].engineer_name,'Reviewer');
